#!/usr/bin/env python3
"""JSON entry point; all computation lives in the scheduling modules."""
import gc
import json
import math
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent))
from utils import run_request


def pairs(items):
    result = {}
    for key, value in items:
        if key in result:
            raise ValueError('duplicate key')
        result[key] = value
    return result


def reject_constant(value):
    raise ValueError('nonfinite number')


def finite(value):
    if isinstance(value, float) and not math.isfinite(value):
        raise ValueError('nonfinite number')
    if isinstance(value, (dict, list)):
        for item in (value.values() if isinstance(value, dict) else value):
            finite(item)


def main():
    # Engine graphs are acyclic and refcounted; avoid repeated full scans of
    # long-lived, shared checkpoint trees by the cyclic collector.
    gc.disable()
    try:
        request = json.loads(sys.stdin.buffer.read().decode('utf-8'),
                             object_pairs_hook=pairs, parse_constant=reject_constant)
        finite(request)
    except (ValueError, UnicodeError, RecursionError):
        print('{"error":"invalid"}')
        return
    response = run_request(request)
    print(json.dumps(response, separators=(',', ':'), allow_nan=False))


if __name__ == '__main__':
    main()
"""JSON experiment adapter. The output log is never part of saved state."""
from scheduler import DynamicIntervalRRPIFOScheduler


def run_experiment(spec):
    scheduler = DynamicIntervalRRPIFOScheduler(spec)
    log = []
    for i, event in enumerate(spec['events']):
        command = event[0]
        if command == 'enqueue':
            log.append(scheduler.enqueue(i, *event[1:]))
            if scheduler.sample_progress == scheduler.sample_period:
                log.append(scheduler.sample(i))
        elif command == 'dequeue':
            for _ in range(event[1]):
                log.append(scheduler.dequeue(i))
        else:
            log.append(getattr(scheduler, command)(i, *event[1:]))
    return {'log': log, 'state': scheduler.certificate()}


def run_request(request):
    return {'runs': [run_experiment(spec) for spec in request['runs']]}
